// لائحة العمل المكتوبة — تظهر لكل الأدوار، والإدارة تحرّرها وتُحفظ مع بيانات مساحة العمل
navs.push(['policy','§','لائحة العمل']);
function policyView(){const p=db.policy&&Array.isArray(db.policy.sections)?db.policy:{version:1,updatedAt:'',updatedBy:'',sections:[]};const meta=p.updatedAt?`<small>آخر تحديث: ${stamp(p.updatedAt)}${p.updatedBy?' • '+esc(p.updatedBy):''} • إصدار ${p.version||1}</small>`:'<small>الإصدار الأساسي للائحة</small>';return card('لائحة العمل — الحضور والبريكات والتأخير',`<div class="policy-meta">${meta}</div>${p.sections.map((s,i)=>`<article class="sales-lead"><h3>${i+1}. ${esc(s.title)}</h3><p style="white-space:pre-wrap">${esc(s.body)}</p></article>`).join('')||'<p class="empty">لم تُنشر اللائحة بعد</p>'}`,role==='الإدارة'?'<button id="policyEdit">تعديل اللائحة</button>':'')+latePolicyCard()}
function latePolicyCard(){const lp=db.latePolicy||{};const rows=[['الأذونات المدفوعة في الشهر',(lp.paidPermissionsPerMonth??2)+' إذن (حضور أو انصراف)'],['مدة الإذن',(lp.permissionWindowMinutes??60)+' دقيقة قبل بداية الشيفت أو بعد نهايته'],['شرط الإذن',lp.requiresReplacement!==false?'وجود بديل وألا يؤثر على سير العمل بالشكل المناسب':'بدون شرط بديل'],['سماح التأخير',(lp.graceMinutes??15)+' دقيقة كحد أقصى'],['تأخير بدون إذن '+(lp.lateTier1Minutes??30)+' دقيقة (بعد السماح)','خصم '+esc(lp.lateTier1Deduction||'ربع شيفت')],['تأخير بدون إذن '+(lp.lateTier2Minutes??60)+' دقيقة (بعد السماح)','خصم '+esc(lp.lateTier2Deduction||'نص شيفت')],['يوم غياب بدون إذن','خصم '+(lp.unreportedAbsenceDeductionDays??2)+' يوم'],['حد أدنى لساعات العمل الشهرية',(lp.minMonthlyHours??210)+' ساعة لكل العاملين (راتب أساسي أو شيفتات)']];return card('قواعد الأذونات وخصومات التأخير — مقترحة وغير مفعّلة في التقفيل بعد',`<div class="notice">القواعد دي مقترحة ولم تدخل حساب المرتبات بعد؛ التفعيل بيتم بعد الاعتماد النهائي من الإدارة.</div><div class="table-wrap"><table>${rows.map(([t,v])=>`<tr><td>${t}</td><td>${v}</td></tr>`).join('')}</table></div>${lp.updatedAt?`<small>آخر تحديث: ${stamp(lp.updatedAt)}${lp.updatedBy?' • '+esc(lp.updatedBy):''}</small>`:''}`,role==='الإدارة'?'<button id="latePolicyEdit">تعديل القواعد المقترحة</button>':'')}
function latePolicyForm(){const lp=db.latePolicy||{};safeSubmit('تعديل قواعد الأذونات وخصومات التأخير','<p>القواعد مقترحة ولا تدخل حساب المرتبات حاليًا؛ التعديل يحفظها كمرجع معلن لحين الاعتماد النهائي.</p>'+field('عدد الأذونات المدفوعة في الشهر','paidPermissionsPerMonth','number',lp.paidPermissionsPerMonth??2)+field('مدة الإذن بالدقائق (قبل أو بعد الشيفت)','permissionWindowMinutes','number',lp.permissionWindowMinutes??60)+field('سماح التأخير بالدقائق','graceMinutes','number',lp.graceMinutes??15)+field('عتبة تأخير بدون إذن — الخصم الأول (دقائق)','lateTier1Minutes','number',lp.lateTier1Minutes??30)+field('خصم العتبة الأولى','lateTier1Deduction','text',lp.lateTier1Deduction||'ربع شيفت')+field('عتبة تأخير بدون إذن — الخصم الثاني (دقائق)','lateTier2Minutes','number',lp.lateTier2Minutes??60)+field('خصم العتبة الثانية','lateTier2Deduction','text',lp.lateTier2Deduction||'نص شيفت')+field('خصم يوم الغياب بدون إذن (بالأيام)','unreportedAbsenceDeductionDays','number',lp.unreportedAbsenceDeductionDays??2)+field('الحد الأدنى لساعات العمل الشهرية','minMonthlyHours','number',lp.minMonthlyHours??210)+'<label class="permission-item"><input type="checkbox" name="requiresReplacement" '+(lp.requiresReplacement!==false?'checked':'')+'>الإذن بشرط وجود بديل وألا يؤثر على سير العمل</label>',f=>{const num=(k,min,max,label)=>{const v=Number(f.get(k));if(!Number.isFinite(v)||v<min||v>max)throw Error('راجع قيمة «'+label+'»');return v};db.latePolicy={paidPermissionsPerMonth:num('paidPermissionsPerMonth',0,31,'عدد الأذونات'),permissionWindowMinutes:num('permissionWindowMinutes',1,240,'مدة الإذن'),requiresReplacement:f.has('requiresReplacement'),graceMinutes:num('graceMinutes',0,120,'سماح التأخير'),lateTier1Minutes:num('lateTier1Minutes',1,480,'عتبة الخصم الأولى'),lateTier1Deduction:String(f.get('lateTier1Deduction')||'ربع شيفت').trim().slice(0,60),lateTier2Minutes:num('lateTier2Minutes',1,480,'عتبة الخصم الثانية'),lateTier2Deduction:String(f.get('lateTier2Deduction')||'نص شيفت').trim().slice(0,60),unreportedAbsenceDeductionDays:num('unreportedAbsenceDeductionDays',0,31,'خصم الغياب بدون إذن'),minMonthlyHours:num('minMonthlyHours',1,744,'حد ساعات الشهر'),active:false,updatedAt:new Date().toISOString(),updatedBy:'الإدارة'};audit('تحديث قواعد الأذونات وخصومات التأخير المقترحة')})}
function policyForm(){const p=db.policy&&Array.isArray(db.policy.sections)?db.policy:{sections:[]};const slots=[...p.sections.map(s=>({title:s.title,body:s.body})),{title:'',body:''},{title:'',body:''}];safeSubmit('تعديل لائحة العمل','<p>اللائحة تظهر لكل الموظفين في صفحة «لائحة العمل». اترك عنوان القسم فاضيًا لحذفه، واستخدم الخانتين الفارغتين بالأسفل لإضافة أقسام جديدة.</p>'+slots.map((s,i)=>`<h3>القسم ${i+1}</h3>${field('العنوان','pt'+i,'text',s.title)}<label>النص<textarea name="pb${i}" rows="4" maxlength="4000">${esc(s.body)}</textarea></label>`).join(''),f=>{const sections=[];for(let i=0;i<slots.length;i++){const title=String(f.get('pt'+i)||'').trim().slice(0,120),body=String(f.get('pb'+i)||'').trim().slice(0,4000);if(title&&body)sections.push({title,body})}if(!sections.length)throw Error('اكتب قسمًا واحدًا على الأقل بعنوان ونص');db.policy={sections,version:(db.policy&&db.policy.version||1)+1,updatedAt:new Date().toISOString(),updatedBy:'الإدارة'};audit('تحديث لائحة العمل — إصدار '+db.policy.version)})}
const policyPrevRender=render;render=function(){policyPrevRender();if(page==='policy'){$('#app').innerHTML=policyView();$('#policyEdit')?.addEventListener('click',policyForm);$('#latePolicyEdit')?.addEventListener('click',latePolicyForm)}};
